() => {
        if (!isSafeUrl(url)) {
            setError(
                'Please enter a valid link.'
            )

            return
        }

        const normalizedUrl =
            normalizeUrl(url)

        const target =
            openInNewTab
                ? '_blank'
                : null

        const rel =
            openInNewTab
                ? 'noopener noreferrer'
                : null

        const {
            empty,
        } = editor.state.selection

        /*
         * Existing link.
         */

        if (editor.isActive('link')) {
            editor
                .chain()
                .focus()
                .extendMarkRange('link')
                .setLink({
                    href: normalizedUrl,
                    target,
                    rel,
                })
                .run()

            onClose()

            return
        }

        /*
         * Selected text.
         */

        if (!empty) {
            if (
                text.trim() &&
                text !== originalText
            ) {
                editor
                    .chain()
                    .focus()
                    .insertContent({
                        type: 'text',

                        text: text.trim(),

                        marks: [
                            {
                                type: 'link',

                                attrs: {
                                    href:
                                        normalizedUrl,

                                    target,

                                    rel,
                                },
                            },
                        ],
                    })
                    .run()
            } else {
                editor
                    .chain()
                    .focus()
                    .setLink({
                        href: normalizedUrl,
                        target,
                        rel,
                    })
                    .run()
            }

            onClose()

            return
        }

        /*
         * No selection.
         *
         * Insert link text directly.
         */

        const linkText =
            text.trim() ||
            normalizedUrl

        editor
            .chain()
            .focus()
            .insertContent({
                type: 'text',

                text: linkText,

                marks: [
                    {
                        type: 'link',

                        attrs: {
                            href: normalizedUrl,
                            target,
                            rel,
                        },
                    },
                ],
            })
            .run()

        onClose()
    }

