async () => {
        try {
            setError('')

            let src =
                imageUrl.trim()

            let storagePath =
                ''

            /*
            |--------------------------------------------------------------------------
            | Uploaded image
            |--------------------------------------------------------------------------
            */

            if (file) {
                setUploading(true)

                const result =
                    await uploadImage(
                        file
                    )

                src =
                    result.url

                storagePath =
                    result.path ??
                    ''
            }

            /*
            |--------------------------------------------------------------------------
            | Validate final image source
            |--------------------------------------------------------------------------
            */

            if (!src) {
                setError(
                    'Please upload an image or enter an image URL.'
                )

                return
            }

            /*
            |--------------------------------------------------------------------------
            | Insert image node
            |--------------------------------------------------------------------------
            */

            editor
                .chain()
                .focus()
                .insertImageFigure({
                    src,

                    path:
                        storagePath,

                    alt:
                        alt.trim(),

                    caption:
                        caption.trim(),

                    align:
                        'center',

                    width:
                        100,
                })
                .run()

            onClose()
        } catch (error) {
            setError(
                error instanceof Error
                    ? error.message
                    : 'Image upload failed.'
            )
        } finally {
            setUploading(
                false
            )
        }
    }

