useEffect(() => {
        if (
            !open ||
            !onNewsSearch
        ) {
            return
        }

        const query =
            searchQuery.trim()

        if (
            query.length <
            2
        ) {
            setSearchResults([])
            setSearchError('')
            setSearching(false)

            return
        }

        const requestId =
            ++searchRequestRef.current

        const timer =
            window.setTimeout(
                async () => {
                    try {
                        setSearching(
                            true
                        )
                        setSearchError(
                            ''
                        )

                        const results =
                            await onNewsSearch(
                                query
                            )

                        if (
                            requestId !==
                            searchRequestRef.current
                        ) {
                            return
                        }

                        setSearchResults(
                            Array.isArray(
                                results
                            )
                                ? results
                                : []
                        )
                    } catch (
                        searchFailure
                    ) {
                        if (
                            requestId !==
                            searchRequestRef.current
                        ) {
                            return
                        }

                        setSearchResults(
                            []
                        )

                        setSearchError(
                            searchFailure instanceof
                                Error
                                ? searchFailure.message
                                : 'News search failed.'
                        )
                    } finally {
                        if (
                            requestId ===
                            searchRequestRef.current
                        ) {
                            setSearching(
                                false
                            )
                        }
                    }
                },
                350
            )

        return () => {
            window.clearTimeout(
                timer
            )
        }
    }, [
        onNewsSearch,
        open,
        searchQuery,
    ])

useEffect(() => {
        if (!open) {
            return
        }

        const handleKeyDown = (
            event: KeyboardEvent
        ) => {
            if (event.key === 'Escape') {
                onClose()
            }
        }

        document.addEventListener(
            'keydown',
            handleKeyDown
        )

        const previousOverflow =
            document.body.style.overflow

        document.body.style.overflow =
            'hidden'

        return () => {
            document.removeEventListener(
                'keydown',
                handleKeyDown
            )

            document.body.style.overflow =
                previousOverflow
        }
    }, [open, onClose])

