export function createEditorExtensions({
    imageUploadUrl =
        '/tiptap-editor/media',

    onImageUpload,
}: EditorExtensionOptions = {}) {
    return [
        StarterKit.configure({
            heading: {
                levels: [
                    1,
                    2,
                    3,
                ],
            },

            link: {
                openOnClick:
                    false,

                autolink:
                    true,

                linkOnPaste:
                    true,

                defaultProtocol:
                    'https',
            },
        }),

        TextAlign.configure({
            types: [
                'heading',
                'paragraph',
            ],

            alignments: [
                'left',
                'center',
                'right',
                'justify',
            ],
        }),

        // Both marks are installed together; one baseline position per character.
        Subscript.extend({ excludes: 'superscript' }),

        Superscript.extend({ excludes: 'subscript' }),

        ImageFigure.configure({
            imageUploadUrl,

            onImageUpload,
        }),

        VideoEmbed,

        NewsBlock,

        CustomTable.configure({
            resizable:
                true,

            lastColumnResizable:
                true,

            allowTableNodeSelection:
                true,
        }),

        TableRow,

        CustomTableHeader,

        CustomTableCell,
    ]
}
